// top-level `summary` aggregates across all entries in `series`.
type UsageResponse struct {
	// Metric Echoes the requested metric name.
	Metric string `json:"metric"`

	// Range Time range and bucket size for a usage query.
	Range  UsageRange    `json:"range"`
	Series []UsageSeries `json:"series"`

	// Summary Aggregate statistics for a usage series. `total`/`rate` are populated for
	// counters; `latest`/`min`/`max`/`average` are populated for gauges. Unused
	// fields are omitted.
	Summary UsageSummary `json:"summary"`

	// Type Aggregation semantics for the metric. `counter` values are summed within
	// each bucket; `gauge` values are averaged within each bucket.
	Type UsageMetricType `json:"type"`

	// Unit Base unit of the metric, e.g. `count`, `tokens`, `millicore_seconds`.
	Unit string `json:"unit"`
}

// One series in a usage response. `project_id` is set when the metric is
// project-scoped and the response is grouped by project; it is omitted
// for org-level metrics or when a `project_id` filter was supplied.
type UsageSeries struct {
	Points    []UsageDataPoint `json:"points"`
	ProjectId *ulid.ULID       `json:"project_id,omitempty"`

	// Summary Aggregate statistics for a usage series. `total`/`rate` are populated for
	// counters; `latest`/`min`/`max`/`average` are populated for gauges. Unused
	// fields are omitted.
	Summary UsageSummary `json:"summary"`
}

// Aggregate statistics for a usage series. `total`/`rate` are populated for
// counters; `latest`/`min`/`max`/`average` are populated for gauges. Unused
// fields are omitted.
